sys_variable_value.value:
(function execute(inputs, outputs) {

    var api = new PlaybookActivityDataProvider();

    var subSysId = String(inputs.param_sub_sysid || '');   // inputs. - not a bare global
    var dataFor  = String(inputs.param_data_for || '').toLowerCase().trim();

    // Always emit valid JSON so downstream JSON.parse never sees null/undefined.
    if (!subSysId) {
        gs.warn('[ActivityUIDataHelper] param_sub_sysid is empty - returning empty sets');
        return;
    }

    if (dataFor === 'extraction') {
        outputs.result1 = '[]';
        outputs.result1 = JSON.stringify(api.getExtractionVersions(subSysId));
        outputs.result2 = "";
        outputs.result3 = ""; 
        outputs.result4 = ""; 
        outputs.result5 = ""; 

    } else if (dataFor === 'mailsanddocs') {
        outputs.result1 = '[]';
        outputs.result2 = '[]';
        outputs.result1 = JSON.stringify(api.getInbox(subSysId));
        outputs.result2 = JSON.stringify(api.getDocuments(subSysId));
        outputs.result3 = ""; 
        outputs.result4 = ""; 
        outputs.result5 = ""; 

    } else if (dataFor === 'partycheck') {
        var partyMatch = api.getPartyMatches(subSysId);
        outputs.result1 = partyMatch.name;          
        outputs.result2 = partyMatch.address;       
        outputs.result3 = partyMatch.asOf;          
        outputs.result4 = partyMatch.matchMessage;  
        outputs.result5 = "";  
    }
    
    
     else {
        gs.warn('[ActivityUIDataHelper] unknown param_data_for "' + dataFor +
                '" - expected "extraction" or "mailsanddocs"');
    }

})(inputs, outputs);

